// One row per bookmaker back price, beside the lowest exchange lay price for the same outcome.
// rating = back / lay x 100. With your commission c as a fraction, the rating after commission is
// back x (1 - c) / (lay - c) x 100, the same figure when c is 0. The prices carry no commission.
const c = Number($('Settings').first().json.commissionPercent) / 100;
const round = (x) => Math.round(x * 100) / 100;
// UK time as yyyy-mm-dd hh:mm, which sorts correctly in a sheet ('sv-SE' writes dates in that order)
const ukTime = (t) => new Date(t).toLocaleString('sv-SE', { timeZone: 'Europe/London' }).slice(0, 16);
const checkedAt = ukTime(Date.now());
const rows = [];

for (const ev of $input.first().json.data ?? []) {
  const event = ev.home_team && ev.away_team ? `${ev.home_team} v ${ev.away_team}` : (ev.event_name ?? ev.venue ?? ev.sport_title);
  for (const market of ev.markets ?? []) {
    for (const o of market.outcomes ?? []) {
      const lays = Array.isArray(o.lay) ? o.lay.filter((l) => l.price > 1) : [];
      if (!lays.length) continue;
      const lay = lays.reduce((low, l) => (l.price < low.price ? l : low));
      const outcome = o.point == null ? o.name : `${o.name} ${o.point}`;
      for (const back of o.back ?? []) {
        if (!(back.price > 1)) continue;
        rows.push({
          json: {
            row_key: [ev.event_id, market.key, outcome, back.bookmaker].join('|'),
            checked_at: checkedAt,
            kick_off: ev.commence_time ? ukTime(ev.commence_time) : '',
            competition: ev.sport_title,
            event,
            market: market.key,
            outcome,
            bookmaker: back.bookmaker,
            back: back.price,
            exchange: lay.exchange,
            lay: lay.price,
            lay_available: lay.available ?? '',
            rating: round((back.price / lay.price) * 100),
            rating_after_commission: round(((back.price * (1 - c)) / (lay.price - c)) * 100),
            back_link: back.link ?? '',
            lay_link: lay.link ?? '',
          },
        });
      }
    }
  }
}

return rows;
